import type { LocaleCode } from '../locales.ts';
import type { Messages } from './en.ts';

/**
 * The assignment page (`/learn/[enrolmentId]/assignment/[assignmentId]`), its
 * written-answer part, and the assignment list on the course page.
 *
 * Same rule as `learn.ts`, `course.ts`, `lesson.ts` and `assess.ts`: written
 * for the twenty-seven languages with nothing held in `held.ts`, and for no
 * other. See `UNWRITTEN_WHILE_HELD`.
 *
 * **What is here** is what the page says itself: the kind of task, the
 * deadline, the draft and hand-in buttons and what they say while they work,
 * the mark, revising and the reasons it may not be offered, earlier versions,
 * and the sentences for a write that was refused or could not be confirmed.
 * Five sentences are the quiz's and are not said twice (`assess.back`,
 * `assess.pointsOne`, `assess.pointsOther`, `assess.score`,
 * `assess.submitting`).
 *
 * The files part of the page is here too (`assign.file*`, forty-five
 * sentences): choosing, checking and uploading a file, and everything it says
 * when storage and the record disagree. Several of those are said when it is
 * not known whether a file arrived or was removed. They say that it is not
 * known and that the list should be checked before sending again; a
 * translation that says "failed" instead would have a learner send a second
 * copy, and one that says "done" would have them hand in without the file.
 *
 * **What is not here.** What a teacher or a learner wrote, and a file's name,
 * are shown as written. File sizes ("25.0 MiB") and the format names PDF,
 * JPEG, PNG and WebP are the same in every language. Why the server refused a
 * file is not said in any language: see `CourseworkFileCode`.
 *
 * **Unreviewed.** No speaker has read any of these. `errUnconfirmed` is what a
 * learner reads when their work may or may not have been saved, and it tells
 * them to copy it somewhere first; a wrong sentence there costs somebody their
 * work. A first-language reader's corrections go in through `/contribute`.
 *
 * `revisionsLeftOne` and `revisionsLeftOther` are chosen by the language's own
 * plural rule, which here knows two categories. Every language below uses one
 * wording for both, a label and then the number, so that it reads correctly
 * with any number in languages whose plurals have more than two forms.
 */
